window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ad36cdd60a7cd2f"]={"versions": [{"id": "FIG-3ad36cdd60a7cd2f", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung der Inter-Core-Kommunikation in AUTOSAR Classic (AUTOSAR_SWS_RTE, Kapitel 4.3.4.3.1). Das Diagramm illustriert das Entwurfsmuster für den Empfang von Daten über das COM-Modul auf einem Master Core und deren Weiterleitung an eine Software-Komponente (SWC) auf einem Slave Core über den Inter-OS-Application-Communicator (IOC) des Betriebssystems.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Partitionen / Cores:</strong></li>\n<li><code>Master Core</code>: Ausführungskontext für COM und die masterseitige RTE-Instanz.</li>\n<li><code>Slave Core</code>: Ausführungskontext für die slaveseitige RTE-Instanz und die anwendungsbezogene SWC.</li>\n<li><strong>Lebenslinien / Entitäten:</strong></li>\n<li><code>COM</code> (Master Core): AUTOSAR-Kommunikationsmodul der Basissoftware zur Signalverarbeitung.</li>\n<li><code>RTE</code> (Master Core): Instanz der Laufzeitumgebung auf dem Master Core.</li>\n<li><code>IOC</code>: Inter-OS-Application-Communicator zur synchronisierten Datenübertragung über Core- und OS-Applikationsgrenzen hinweg.</li>\n<li><code>RTE</code> (Slave Core): Lokale RTE-Instanz auf dem Slave Core.</li>\n<li><code>SWC</code> (Slave Core): Anwendungs-Software-Komponente als Datenempfänger.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>Com_cbk(x)</code>: COM-Callback/Rx-Indikation zur Signalübergabe des Werts <code>x</code> an die Master-RTE.</li>\n<li><code>IocSend_&lt;id&gt;(x)</code>: Queued IOC-Schnittstelle zur Einreihung des Nutzdatums <code>x</code> in eine FIFO-Warteschlange des IOC.</li>\n<li><code>Rte_Read()</code>: Standardisierte RTE-Lese-API der SWC (Sender-Receiver-Kommunikation).</li>\n<li><code>IocReceive_&lt;id&gt;(&amp;x)</code>: Queued IOC-Schnittstelle zum Auslesen des nächsten Datenelements aus der Warteschlange über den Zeigerparameter <code>&amp;x</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>COM-Indikation (Master Core):</strong> Das COM-Modul signalisiert den Empfang eines neuen Signalwerts synchron über den Aufruf <code>Com_cbk(x)</code> an die masterseitige RTE.</li>\n<li><strong>Core-übergreifendes Queued-Senden (IOC):</strong> Die Master-RTE leitet den Signalwert unverzüglich über <code>IocSend_&lt;id&gt;(x)</code> an den IOC weiter. Der Aufruf wird vom IOC synchron quittiert und kehrt zur Master-RTE zurück.</li>\n<li><strong>SWC-Leseanfrage (Slave Core):</strong> Zeitlich entkoppelt ruft die SWC auf dem Slave Core <code>Rte_Read()</code> an der lokalen Slave-RTE auf.</li>\n<li><strong>Core-übergreifendes Queued-Empfangen (IOC):</strong> Die Slave-RTE ruft daraufhin <code>IocReceive_&lt;id&gt;(&amp;x)</code> am IOC auf, um den nächsten gepufferten Signalwert abzuholen. Der IOC übergibt den Wert über den Zeigerparameter <code>&amp;x</code> und kehrt zur Slave-RTE zurück.</li>\n<li><strong>Rückgabe an SWC:</strong> Die Slave-RTE liefert das empfangene Datum an die aufrufende SWC zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informatives Beispielsequenzdiagramm (\"may be implemented by RTE\") für Entwickler von RTE-Generatoren und Basissoftware. Die Sequenz zeigt eine gequeuete Inter-Core-Sender-Receiver-Kommunikation mittels <code>IocSend</code> und <code>IocReceive</code>. Dies bedingt eine FIFO-Pufferung im OS-IOC, um zeitlichen Versatz oder unterschiedliche Verarbeitungsgeschwindigkeiten zwischen COM-Rx-Ereignissen und SWC-Lesezyklen verlustfrei abzufangen.</p>"}, {"id": "FIG-bf623f1b2d7e6201", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung der Inter-Core-Kommunikation in AUTOSAR Classic (AUTOSAR_SWS_RTE, Kapitel 4.3.4.3.1). Das Diagramm illustriert das Entwurfsmuster für den Empfang von Daten über das COM-Modul auf einem Master Core und deren Weiterleitung an eine Software-Komponente (SWC) auf einem Slave Core über den Inter-OS-Application-Communicator (IOC) des Betriebssystems.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Partitionen / Cores:</strong></li>\n<li><code>Master Core</code>: Ausführungskontext für COM und die masterseitige RTE-Instanz.</li>\n<li><code>Slave Core</code>: Ausführungskontext für die slaveseitige RTE-Instanz und die anwendungsbezogene SWC.</li>\n<li><strong>Lebenslinien / Entitäten:</strong></li>\n<li><code>COM</code> (Master Core): AUTOSAR-Kommunikationsmodul der Basissoftware zur Signalverarbeitung.</li>\n<li><code>RTE</code> (Master Core): Instanz der Laufzeitumgebung auf dem Master Core.</li>\n<li><code>IOC</code>: Inter-OS-Application-Communicator zur synchronisierten Datenübertragung über Core- und OS-Applikationsgrenzen hinweg.</li>\n<li><code>RTE</code> (Slave Core): Lokale RTE-Instanz auf dem Slave Core.</li>\n<li><code>SWC</code> (Slave Core): Anwendungs-Software-Komponente als Datenempfänger.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>Com_cbk(x)</code>: COM-Callback/Rx-Indikation zur Signalübergabe des Werts <code>x</code> an die Master-RTE.</li>\n<li><code>IocWrite_&lt;id&gt;(x)</code>: Nicht-gequeute (Last-is-Best / Data Semantics) IOC-Schnittstelle zum atomaren Überschreiben des Kanalwerts <code>x</code>.</li>\n<li><code>Rte_Read()</code>: Standardisierte RTE-Lese-API der SWC (Sender-Receiver-Kommunikation).</li>\n<li><code>IocRead_&lt;id&gt;(&amp;x)</code>: Nicht-gequeute IOC-Schnittstelle zum atomaren Auslesen des aktuellen Kanalwerts über den Zeigerparameter <code>&amp;x</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>COM-Indikation (Master Core):</strong> Das COM-Modul signalisiert den Empfang eines neuen Signalwerts synchron über den Aufruf <code>Com_cbk(x)</code> an die masterseitige RTE.</li>\n<li><strong>Core-übergreifendes Unqueued-Schreiben (IOC):</strong> Die Master-RTE schreibt den empfangenen Wert über <code>IocWrite_&lt;id&gt;(x)</code> in den IOC. Der Aufruf wird synchron vom IOC quittiert und kehrt zur Master-RTE zurück.</li>\n<li><strong>SWC-Leseanfrage (Slave Core):</strong> Zeitlich entkoppelt ruft die SWC auf dem Slave Core <code>Rte_Read()</code> an der lokalen Slave-RTE auf.</li>\n<li><strong>Core-übergreifendes Unqueued-Lesen (IOC):</strong> Die Slave-RTE fragt über <code>IocRead_&lt;id&gt;(&amp;x)</code> den aktuellen Signalwert atomar vom IOC ab. Der IOC übergibt den Wert über den Zeigerparameter <code>&amp;x</code> und kehrt zur Slave-RTE zurück.</li>\n<li><strong>Rückgabe an SWC:</strong> Die Slave-RTE liefert das gelesene Datum an die aufrufende SWC zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informatives Beispielsequenzdiagramm (\"may be implemented by RTE\") für Entwickler von RTE-Generatoren und Basissoftware. Die Sequenz spezifiziert nun die Verwendung von unqueued IOC-Kommunikationsdiensten (<code>IocWrite</code> / <code>IocRead</code>) für unqueued Sender-Receiver-Kommunikation (Data Semantics / Last-is-Best). Entwickler müssen beachten, dass hierbei keine FIFO-Pufferung stattfindet; neu eintreffende COM-Signale überschreiben den vorherigen Wert im IOC-Puffer, und mehrfache Aufrufe von <code>Rte_Read()</code> ohne zwischenzeitlichen COM-Empfang lesen denselben Signalwert wiederholt.</p>"}], "trans": [{"from": "FIG-3ad36cdd60a7cd2f", "to": "FIG-bf623f1b2d7e6201", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ersetzung der IOC-Schnittstellenfunktion auf dem Master Core: <code>IocSend_&lt;id&gt;(x)</code> wurde durch <code>IocWrite_&lt;id&gt;(x)</code> ersetzt (Wechsel von gequeueter zu nicht-gequeueter IOC-Kommunikation).</li>\n<li>Ersetzung der IOC-Schnittstellenfunktion auf dem Slave Core: <code>IocReceive_&lt;id&gt;(&amp;x)</code> wurde durch <code>IocRead_&lt;id&gt;(&amp;x)</code> ersetzt (Wechsel von gequeueter zu nicht-gequeueter IOC-Kommunikation).</li>\n</ul>"}]};
